  const priority=name=>/^(qty|quantity|weight|pack\s*size|size|volume)$/i.test(name.trim())?0:/^(variant|type|flavour|flavor|colour|color)$/i.test(name.trim())?1:2;
  names.sort((a,b)=>priority(a)-priority(b));
