 {(()=>{const q=search.trim().toLocaleLowerCase();const filtered=items.filter(p=>[p.name,p.sku,p.brand,p.category,p.category_path,p.variant_type_name,p.variant_type,p.variant_value,p.variant_type_value,p.variant_short,p.attribute_name,p.attribute_value,p.quantity_label,p.weight,p.pack_size,p.unit,p.size].some(v=>String(v??'').toLocaleLowerCase().includes(q)));const pages=Math.max(1,Math.ceil(filtered.length/pageSize));const safePage=Math.min(page,pages);const visible=filtered.slice((safePage-1)*pageSize,safePage*pageSize);return <><p className="catalogue-result-count">Showing {filtered.length?((safePage-1)*pageSize+1):0}–{Math.min(safePage*pageSize,filtered.length)} of {filtered.length} matching variants ({items.length} total loaded)</p><div className="user-table-wrap"><table className="user-table"><thead><tr><th>Product / variant</th><th>SKU</th><th>Price</th><th>Status</th><th></th></tr></thead><tbody>{visible.map(p=>{const scalarValue=v=>v!=null&&typeof v!=='object'?String(v).trim():'';const rawAttributes=p.attributes??p.attribute_values??p.variant_attributes;let parsedAttributes=rawAttributes;if(typeof rawAttributes==='string'){try{parsedAttributes=JSON.parse(rawAttributes)}catch{parsedAttributes=null}}const attributeRows=Array.isArray(parsedAttributes)?parsedAttributes:parsedAttributes&&typeof parsedAttributes==='object'?Object.entries(parsedAttributes).filter(([key,value])=>!key.startsWith('_')&&value!=null&&typeof value!=='object'&&!['brand','sku','id','source'].includes(key.toLowerCase())).map(([attribute_name,attribute_value])=>({attribute_name,attribute_value})):[];const readableAttributes=attributeRows.map(a=>{if(!a||typeof a!=='object')return '';const name=String(a.attribute_name||a.name||a.label||'').trim().toLowerCase();if(['brand','sku','id','source'].includes(name)||name.startsWith('_'))return '';const value=a.attribute_value||a.value_name||a.value||a.display_value||a.display_name||a.label_value||'';return value!=null&&String(value).trim()?String(value).trim():''}).filter(Boolean);const variantValue=readableAttributes.join(', ')||[p.variant_value,p.attribute_value,p.variant_type_value,p.quantity_label,p.weight,p.pack_size,p.size,p.unit,p.variant_name,p.variant_description,p.variant_label,p.variant_short].map(scalarValue).find(v=>v&&v!==scalarValue(p.sku)&&!/^ODOO-VAR-\d+$/i.test(v))||'';const coverImage=p.image_url||(Array.isArray(p.gallery_images)?(p.gallery_images.find(image=>image&&image.image_url)||{}).image_url:'');return <tr key={p.variant_id||p.product_id}><td><div style={{display:'flex',alignItems:'center',gap:'10px'}}>{coverImage?<img src={coverImage} alt={p.name+' cover'} loading="lazy" style={{width:'44px',height:'44px',objectFit:'contain',borderRadius:'8px',flexShrink:0}}/>:<div aria-label="No cover image" style={{width:'44px',height:'44px',borderRadius:'8px',display:'grid',placeItems:'center',flexShrink:0}}>—</div>}<div><b>{p.name}{variantValue?' ('+variantValue+')':''}</b><small>{p.brand||''}</small></div></div></td><td>{p.sku||'—'}</td><td>{money(p.selling_price)}</td><td>{p.status||'active'}</td><td><button className="outline-action" onClick={()=>start(p)}>Edit</button></td></tr>})}</tbody></table>{visible.length===0&&<p className="catalogue-empty">No products match “{search}”. Try another name, SKU or brand.</p>}</div><div className="catalogue-pagination"><span>Page {safePage} of {pages}</span><div><button className="outline-action" disabled={safePage<=1} onClick={()=>setPage(Math.max(1,safePage-1))}>← Previous</button><button className="outline-action" disabled={safePage>=pages} onClick={()=>setPage(Math.min(pages,safePage+1))}>Next →</button></div></div></>})()}
