 async function request(path,options={}){const r=await fetch(API_PATH(path),{...options,headers:{Authorization:'Bearer '+token(),...(options.headers||{})}});const j=await r.json().catch(()=>({}));if(!r.ok)throw Error(j.detail||'Request failed');return j}
