 useEffect(()=>{load()},[]);
 async function saveTiers(){setBusy(true);setMessage('');try{const body={tiers:tiers.map((t,i)=>({name:t.name,min_lifetime_earned:Number(t.min_lifetime_earned),earn_multiplier:Number(t.earn_multiplier),benefits:Array.isArray(t.benefits)?t.benefits:[],is_active:Boolean(t.is_active),sort_order:Number(t.sort_order??i)}))};const j=await request('/loyalty/tiers',{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)});setTiers(j.tiers||[]);setMessage('Custom loyalty tiers saved.')}catch(e){setMessage(e.message||'Tier save failed')}finally{setBusy(false)}}
